mapper.select:
SELECT sum(ifnull( b.total_pay_amount, 0 )) AS actualPayAmountLong, a.biz_dept_id AS bizDeptId FROM contract_base_info AS a INNER JOIN ( SELECT contract_id, min( paid_in_date ) AS min_paid_in_date, sum( paid_in_amount ) AS total_pay_amount FROM payment_actual_detail GROUP BY contract_id ) AS b ON b.contract_id = a.id LEFT JOIN corp_commerce_info corp ON corp.client_id = a.client_id
b.total_pay_amount > 0
AND b.min_paid_in_date >= #{queryDateFrom}
AND b.min_paid_in_date <= #{queryDateTo}
AND corp.risk_control_industry_classify in
#{item}
AND a.biz_dept_id in
#{item}
GROUP BY a.biz_dept_id

select.if:
( SELECT a.origin_id as id, 'CURRENCY' as type, a.biz_dept_id as bizDeptId, c.risk_control_industry_classify as riskControl, case a.biz_type when 'ZR' then IFNULL(f.apply_credit_amount,0) when 'BL' then IFNULL(e.apply_credit_amount,0) else IFNULL(d.apply_credit_amount,0) end as amountLong FROM proj_establish_base_info_lib a join ( select origin_id,max(create_time) max_create_time from proj_establish_base_info_lib group by origin_id ) el2 on a.create_time = el2.max_create_time and a.origin_id = el2.origin_id left join ( select b1.client_id, b1.risk_control_industry_classify from corp_commerce_info_lib b1 join ( select client_id,max(version) max_version from corp_commerce_info_lib where version_type = 1 GROUP BY client_id ) b2 on b2.client_id = b1.client_id and b2.max_version = b1.version ) c on a.client_id = c.client_id left join proj_establish_lease_price as d on a.origin_id = d.proj_establish_id left join proj_establish_factoring_price as e on a.origin_id = e.proj_establish_id left join proj_establish_aoc_price as f on a.origin_id = f.proj_establish_id WHERE a.proj_establish_process_status = 'NEW_APPROVAL_PASS'
and c.risk_control_industry_classify in
#{item}
and a.create_time >= #{queryDateFrom}
and a.create_time <= #{queryDateTo}
AND a.biz_dept_id in
#{item}
) union ALL ( SELECT a.origin_id as id, 'LAST' as type, a.biz_dept_id as bizDeptId, c.risk_control_industry_classify as riskControl, case a.biz_type when 'ZR' then IFNULL(f.apply_credit_amount,0) when 'BL' then IFNULL(e.apply_credit_amount,0) else IFNULL(d.apply_credit_amount,0) end as amountLong FROM proj_establish_base_info_lib a join ( select origin_id,max(create_time) max_create_time from proj_establish_base_info_lib group by origin_id ) el2 on a.create_time = el2.max_create_time and a.origin_id = el2.origin_id left join ( select b1.client_id, b1.risk_control_industry_classify from corp_commerce_info_lib b1 join ( select client_id,max(version) max_version from corp_commerce_info_lib where version_type = 1 GROUP BY client_id ) b2 on b2.client_id = b1.client_id and b2.max_version = b1.version ) c on a.client_id = c.client_id left join proj_establish_lease_price as d on a.origin_id = d.proj_establish_id left join proj_establish_factoring_price as e on a.origin_id = e.proj_establish_id left join proj_establish_aoc_price as f on a.origin_id = f.proj_establish_id WHERE a.proj_establish_process_status = 'NEW_APPROVAL_PASS'
and c.risk_control_industry_classify in
#{item}
and a.create_time >= #{queryDateLastFrom}
and a.create_time <= #{queryDateLastTo}
AND a.biz_dept_id in
#{item}
)

( SELECT a.origin_id as id, 'CURRENCY' as type, a.biz_dept_id as bizDeptId, c.risk_control_industry_classify as riskControl, case a.biz_type when 'ZR' then IFNULL(f.apply_credit_amount,0) when 'BL' then IFNULL(e.apply_credit_amount,0) else IFNULL(d.apply_credit_amount,0) end as amountLong FROM proj_review_base_info_lib a join ( select origin_id,max(create_time) max_create_time from proj_review_base_info_lib group by origin_id ) el2 on a.create_time = el2.max_create_time and a.origin_id = el2.origin_id left join ( select b1.client_id, b1.risk_control_industry_classify from corp_commerce_info_lib b1 join ( select client_id,max(version) max_version from corp_commerce_info_lib where version_type = 1 GROUP BY client_id ) b2 on b2.client_id = b1.client_id and b2.max_version = b1.version ) c on a.client_id = c.client_id left join proj_review_lease_price as d on a.origin_id = d.project_id left join proj_review_factoring_price as e on a.origin_id = e.project_id left join proj_review_aoc_price as f on a.origin_id = f.project_id WHERE a.proj_review_process_status = 'NEW_APPROVAL_PASS'
and c.risk_control_industry_classify in
#{item}
and a.create_time >= #{queryDateFrom}
and a.create_time <= #{queryDateTo}
AND a.biz_dept_id in
#{item}
