and c.risk_control_industry_classify in
#{item}
and a.create_time >= #{queryDateLastFrom}
and a.create_time <= #{queryDateLastTo}
AND a.biz_dept_id in
#{item}
)

( SELECT a.id as id, 'CURRENCY' as type, a.dept_id AS bizDeptId, c.risk_control_industry_classify as riskControl, ifnull( a.amount, 0 ) AS amountLong from dashboard_due_diligence_info a left join proj_establish_base_info b on a.proj_code = b.proj_code left join group_credit_establish_base_info jtb on a.proj_code = jtb.proj_code left join ( select b1.client_id, b1.risk_control_industry_classify from corp_commerce_info_lib b1 join ( select client_id,max(version) max_version from corp_commerce_info_lib where version_type = 1 GROUP BY client_id ) b2 on b2.client_id = b1.client_id and b2.max_version = b1.version ) c on b.client_id = c.client_id or jtb.client_id = c.client_id WHERE a.amount > 0
and a.business_group = '${type}'
and a.due_diligence_time >= #{queryDateFrom}
and a.due_diligence_time <= #{queryDateTo}
AND a.dept_id in
#{item}
) union all ( SELECT a.id as id, 'LAST' as type, a.dept_id AS bizDeptId, c.risk_control_industry_classify as riskControl, ifnull( a.amount, 0 ) AS amountLong from dashboard_due_diligence_info a left join proj_establish_base_info b on a.proj_code = b.proj_code left join group_credit_establish_base_info jtb on a.proj_code = jtb.proj_code left join ( select b1.client_id, b1.risk_control_industry_classify from corp_commerce_info_lib b1 join ( select client_id,max(version) max_version from corp_commerce_info_lib where version_type = 1 GROUP BY client_id ) b2 on b2.client_id = b1.client_id and b2.max_version = b1.version ) c on b.client_id = c.client_id or jtb.client_id = c.client_id WHERE a.amount > 0
and a.business_group = '${type}'
and a.due_diligence_time >= #{queryDateLastFrom}
and a.due_diligence_time <= #{queryDateLastTo}
AND a.dept_id in
#{item}
)

( SELECT a.id as id, 'CURRENCY' as type, a.biz_dept_id AS bizDeptId, c.risk_control_industry_classify as riskControl, ifnull( b.total_pay_amount, 0 ) AS amountLong FROM contract_base_info AS a INNER JOIN ( SELECT contract_id, min( paid_in_date ) AS min_paid_in_date, sum( paid_in_amount ) AS total_pay_amount FROM payment_actual_detail GROUP BY contract_id ) AS b ON b.contract_id = a.id left join ( select b1.client_id, b1.risk_control_industry_classify from corp_commerce_info_lib b1 join ( select client_id,max(version) max_version from corp_commerce_info_lib where version_type = 1 GROUP BY client_id ) b2 on b2.client_id = b1.client_id and b2.max_version = b1.version ) c on a.client_id = c.client_id WHERE b.total_pay_amount > 0
and c.risk_control_industry_classify in
#{item}
and b.min_paid_in_date >= #{queryDateFrom}
and b.min_paid_in_date <= #{queryDateTo}
AND a.biz_dept_id in
#{item}
) union all ( SELECT a.id as id, 'LAST' as type, a.biz_dept_id AS bizDeptId, c.risk_control_industry_classify as riskControl, ifnull( b.total_pay_amount, 0 ) AS amountLong FROM contract_base_info AS a INNER JOIN ( SELECT contract_id, min( paid_in_date ) AS min_paid_in_date, sum( paid_in_amount ) AS total_pay_amount FROM payment_actual_detail GROUP BY contract_id ) AS b ON b.contract_id = a.id left join ( select b1.client_id, b1.risk_control_industry_classify from corp_commerce_info_lib b1 join ( select client_id,max(version) max_version from corp_commerce_info_lib where version_type = 1 GROUP BY client_id ) b2 on b2.client_id = b1.client_id and b2.max_version = b1.version ) c on a.client_id = c.client_id WHERE b.total_pay_amount > 0
